        function generateExportHTML() {
            const branchFilter = document.getElementById('branchFilter');
            const filterText = branchFilter.options[branchFilter.selectedIndex].text;
            
            // Get KPIs
            const kpiCards = document.querySelectorAll('#kpiContainer .card');
            let kpiHtml = '';
            if (kpiCards.length === 6) {
                const vals = Array.from(kpiCards).map(c => c.querySelector('.kpi-val').innerText);
                kpiHtml = `
                <table style="width:100%; margin-bottom:20px; border-collapse: collapse; border: none;">
                    <tr>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#eff6ff; text-align:center; width:16%;">
                            <div style="color:#1d4ed8; font-weight:bold; font-size:18px;">${vals[0]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">إجمالي الجامعة</div>
                        </td>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#fee2e2; text-align:center; width:16%;">
                            <div style="color:#b91c1c; font-weight:bold; font-size:18px;">${vals[1]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">الموظفين المتأخرين</div>
                        </td>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#fefce8; text-align:center; width:16%;">
                            <div style="color:#a16207; font-weight:bold; font-size:18px;">${vals[2]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">نسبة المتأخرين</div>
                        </td>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#ffedd5; text-align:center; width:16%;">
                            <div style="color:#c2410c; font-weight:bold; font-size:18px;">${vals[3]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">إجمالي الحالات</div>
                        </td>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#faf5ff; text-align:center; width:16%;">
                            <div style="color:#7e22ce; font-weight:bold; font-size:18px;">${vals[4]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">إجمالي الدقائق</div>
                        </td>
                        <td style="border:1px solid #ddd; padding:10px; background-color:#e0e7ff; text-align:center; width:16%;">
                            <div style="color:#4338ca; font-weight:bold; font-size:18px;">${vals[5]}</div>
                            <div style="color:#6b7280; font-size:12px; font-weight:bold;">إجمالي الساعات</div>
                        </td>
                    </tr>
                </table>
                `;
            }

            // Process Employees Table
            const empContainerClone = document.getElementById('employeesSection').cloneNode(true);
                
            // Clean up tailwind classes and inject inline styles
            const branchGroups = empContainerClone.querySelectorAll('.branch-group');
            branchGroups.forEach(bg => {
                bg.style.marginTop = '30px';
                bg.style.marginBottom = '10px';
                const h2 = bg.querySelector('h2');
                if (h2) {
                    h2.style.fontSize = '24px';
                    h2.style.fontWeight = 'bold';
                    h2.style.color = '#1e3a8a';
                    h2.style.borderBottom = '3px solid #3b82f6';
                    h2.style.paddingBottom = '5px';
                    h2.style.marginBottom = '10px';
                    h2.style.display = 'block';
                }
            });
                
            const rows = empContainerClone.querySelectorAll('tr');
            rows.forEach(row => {
                const spans = row.querySelectorAll('span');
                spans.forEach(span => {
                    if (span.classList.contains('bg-red-100')) {
                        span.style.backgroundColor = '#fee2e2';
                        span.style.color = '#991b1b';
                        span.style.fontWeight = 'bold';
                        span.style.padding = '2px 6px';
                        span.style.borderRadius = '4px';
                    } else if (span.classList.contains('bg-blue-100')) {
                        span.style.backgroundColor = '#dbeafe';
                        span.style.color = '#1e40af';
                        span.style.padding = '2px 6px';
                        span.style.borderRadius = '4px';
                    } else if (span.classList.contains('bg-white')) {
                        span.style.backgroundColor = '#ffffff';
                        span.style.color = '#1e3a8a';
                        span.style.border = '1px solid #bfdbfe';
                        span.style.padding = '4px 10px';
                        span.style.borderRadius = '15px';
                        span.style.display = 'inline-block';
                        span.style.margin = '4px';
                        span.style.fontSize = '12px';
                    }
                });
            });

            let html = `
            <div style="direction: rtl; font-family: 'Arial', sans-serif;">
                <h1 style="text-align:center; color:#1e3a8a; font-size:26px; margin-bottom:5px; font-weight:bold;">التقرير الشامل لتأخير الموظفين</h1>
                <h2 style="text-align:center; color:#4b5563; font-size:18px; margin-bottom:20px;">${filterText}</h2>
                ${kpiHtml}
            `;

            if (document.getElementById('branchesSection').style.display !== 'none') {
                const brTable = document.getElementById('branchesTableBody').parentElement.cloneNode(true);
                html += `<h2 style="color:#1e3a8a; font-size:20px; font-weight:bold; border-bottom: 2px solid #1e3a8a; padding-bottom:5px;">ملخص الفروع والدوائر</h2>`;
                html += brTable.outerHTML;
                html += `<br><br>`;
            }

            html += `<h2 style="color:#1e3a8a; font-size:20px; font-weight:bold; border-bottom: 2px solid #1e3a8a; padding-bottom:5px;">تفاصيل الموظفين</h2>`;
            html += empContainerClone.innerHTML;
            html += `</div>`;
            return html;
        }

        function exportToWord() {
            const exportHtml = generateExportHTML();
            const content = `
                <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
                <head>
                    <meta charset="utf-8">
                    <title>تقرير التأخيرات</title>
                    <style>
                        body { font-family: 'Arial', sans-serif; direction: rtl; }
                        table { border-collapse: collapse; width: 100%; margin-bottom: 20px; font-size: 11px; }
                        th, td { border: 1px solid #94a3b8; padding: 8px; text-align: center; vertical-align: middle; }
                        th { background-color: #1e3a8a; color: white; font-weight: bold; }
                        tr:nth-child(even) { background-color: #f8fafc; }
                        @page WordSection1 {
                            size: 29.7cm 21cm; /* Landscape */
                            mso-page-orientation: landscape;
                            margin: 1cm 1cm 1cm 1cm;
                            mso-header-margin: 35.4pt; mso-footer-margin: 35.4pt;
                            mso-footer: f1;
                        }
                        div.WordSection1 { page: WordSection1; }
                    </style>
                </head>
                <body>
                    <div class="WordSection1">
                        ${exportHtml}
                    </div>
                    <div style="mso-element:footer" id="f1">
                        <p style="text-align:center; color:#6b7280; font-size:10px;">
                            الصفحة <span style="mso-field-code:' PAGE '"></span> من <span style="mso-field-code:' NUMPAGES '"></span>
                        </p>
                    </div>
                </body>
                </html>
            `;
            const blob = new Blob(['﻿', content], { type: 'application/msword' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            const branchFilter = document.getElementById('branchFilter');
            const branchName = branchFilter.options[branchFilter.selectedIndex].text;
            const fileName = `تقرير_التأخيرات_${branchName.replace(/[\/?*\[\]:]/g, '')}.doc`;
            link.download = fileName;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        function exportToExcel() {
            const wb = XLSX.utils.book_new();
            wb.Workbook = { Views: [{ RTL: true }] };
            
            const wsCols = [
                {wch: 5}, {wch: 25}, {wch: 35}, {wch: 15}, {wch: 15}, 
                {wch: 15}, {wch: 15}, {wch: 25}, {wch: 15}
            ];
            
            if (document.getElementById('branchFilter').value.startsWith('all')) {
                const branchesTable = document.getElementById('branchesSection').getElementsByTagName('table')[0];
                const wsBranches = XLSX.utils.table_to_sheet(branchesTable);
                wsBranches['!cols'] = [{wch: 35}, {wch: 20}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 20}, {wch: 15}, {wch: 15}, {wch: 35}, {wch: 20}];
                XLSX.utils.book_append_sheet(wb, wsBranches, "ملخص الفروع");
            }
            
            // For excel, we might have multiple tables now if grouped by branch. Let's just collect all rows.
            // Since Excel export is simpler, we can just grab all tables with class 'branch-table'
            const tables = document.querySelectorAll('.branch-table');
            if (tables.length === 1) {
                const wsEmployees = XLSX.utils.table_to_sheet(tables[0]);
                wsEmployees['!cols'] = wsCols;
                XLSX.utils.book_append_sheet(wb, wsEmployees, "تفاصيل الموظفين");
            } else {
                // Combine tables or just let the first one be used. Better to just let user use 'All by Employee' for flat excel.
                const wsEmployees = XLSX.utils.table_to_sheet(tables[0]);
                wsEmployees['!cols'] = wsCols;
                XLSX.utils.book_append_sheet(wb, wsEmployees, "تفاصيل الموظفين");
            }
            
            XLSX.writeFile(wb, "تصدير_البيانات.xlsx");
        }

